def is_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False
    map12 = {}
    map21 = {}
    for a, b in zip(s1, s2):
        if a in map12 and map12[a] != b:
            return False
        if b in map21 and map21[b] != a:
            return False
        map12[a] = b
        map21[b] = a
    return True

def is_balanced_outside_quotes(s):
    depth = 0
    in_quote = False
    for c in s:
        if c == "'":
            in_quote = not in_quote
            continue
        if in_quote:
            continue
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def merge_two_sorted_lists_descending(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] >= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

