def extended_gcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    return (old_r, old_s, old_t)

def is_valid_non_blocked_email(s, blocked_domains):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or '.' not in domain:
        return False
    if not all(c.isalnum() or c in '._+-' for c in local):
        return False
    labels = domain.split('.')
    for label in labels:
        if not label or not all(c.isalnum() or c == '-' for c in label):
            return False
    blocked_lower = {d.lower() for d in blocked_domains}
    return domain.lower() not in blocked_lower

def has_alternating_vowel_consonant(s):
    vowels = set("aeiouAEIOU")
    letters = [c for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        prev_v = letters[i - 1] in vowels
        cur_v = letters[i] in vowels
        if prev_v == cur_v:
            return False
    return True

def toggle_case_at_indices(s, indices):
    idx_set = set(indices)
    result = []
    for i, c in enumerate(s):
        if i in idx_set:
            result.append(c.swapcase())
        else:
            result.append(c)
    return "".join(result)

