def zigzag_convert(s, num_rows):
    if num_rows <= 1 or num_rows >= len(s):
        return s
    rows = [''] * num_rows
    cur = 0
    step = 1
    for ch in s:
        rows[cur] += ch
        if cur == 0:
            step = 1
        elif cur == num_rows - 1:
            step = -1
        cur += step
    return ''.join(rows)

